# Tests only a disposable database copy; never creates fixture records in the running local database.
from pathlib import Path
import sqlite3,subprocess,tempfile,socket,time,urllib.request
root=Path.cwd();runtime=root.parent/'work/pocketbase';stage=Path(tempfile.mkdtemp(prefix='child-assignments-rehearsal-'))
for folder in ['data','migrations','hooks']:(stage/folder).mkdir()
with sqlite3.connect((runtime/'pb_data/data.db').resolve().as_uri()+'?mode=ro',uri=True) as a,sqlite3.connect(stage/'data/data.db') as b:a.backup(b)
import shutil
shutil.copy2(root/'pb_migrations/1794700000_expert_client_assignments.js',stage/'migrations/1794700000_expert_client_assignments.js')
(stage/'migrations/1794700100_private_expert_fixture.js').write_text('migrate(app=>{\n const mail=app.settings();mail.smtp.enabled=false;app.save(mail);\n const users=app.findCollectionByNameOrId("users")\n function user(email,role){const u=new Record(users);u.set("email",email);u.set("name",role);u.set("password","PrivateTest123!");u.set("role",role);u.set("is_active",true);app.save(u);return u}\n const parent=user("assignment-parent@example.test","parent"),other=user("assignment-other@example.test","parent"),expert=user("assignment-expert@example.test","expert"),foreign=user("assignment-foreign@example.test","expert")\n const roles=app.findCollectionByNameOrId("roles_management"),allocations=app.findCollectionByNameOrId("case_experts")\n // Tool assignment must work without a role_id.\n \n const type=app.findFirstRecordByFilter("lookups",\'type = "tool_types" && key = "multiple_answer"\')\n const role=new Record(roles);role.set("role_name_en","Private assignment role");role.set("role_group","education");role.set("tool_types",[type.id]);app.save(role)\n const c=new Record(app.findCollectionByNameOrId("cases"));c.set("name","Private assigned case");c.set("user",parent.id);c.set("status","active");app.save(c)\n const a=new Record(allocations);a.set("case_id",c.id);a.set("expert_id",expert.id);app.save(a)\n function tool(name,status,typeId){const t=new Record(app.findCollectionByNameOrId("tools"));t.set("name_en",name);t.set("status",status);t.set("type",typeId);t.set("config",{title:{en:name,ar:""},questions:[{id:"answer",text:"Write a short paragraph about your day.",answerType:"text",options:[],required:true,order:1}],media:[]});app.save(t);return t}\n tool("Practice writing","active",type.id);tool("Inactive template","inactive",type.id)\n const otherType=app.findFirstRecordByFilter("lookups",\'type = "tool_types" && key = "survey"\');tool("Forbidden template","active",otherType.id)\n const missingCase=new Record(app.findCollectionByNameOrId("cases"));missingCase.set("name","Uncorrected allocation case");missingCase.set("user",parent.id);missingCase.set("status","active");app.save(missingCase)\n const missingAllocation=new Record(allocations);missingAllocation.set("case_id",missingCase.id);missingAllocation.set("expert_id",expert.id);app.save(missingAllocation)\n})',encoding='utf-8')
r=subprocess.run([str(runtime/'pocketbase.exe'),'migrate','up','--dir='+str(stage/'data'),'--migrationsDir='+str(stage/'migrations'),'--hooksDir='+str(stage/'hooks')],capture_output=True,text=True);print(r.stdout+r.stderr);assert 'Applied 1794700100_private_expert_fixture' in r.stdout+r.stderr
with socket.socket() as sock:sock.bind(('127.0.0.1',0));port=sock.getsockname()[1]
log=open(stage/'server.log','w');server=subprocess.Popen([str(runtime/'pocketbase.exe'),'serve','--http=127.0.0.1:'+str(port),'--dir='+str(stage/'data'),'--migrationsDir='+str(stage/'migrations'),'--hooksDir='+str(root/'pb_hooks'),'--automigrate=false'],stdout=log,stderr=log)
try:
 base='http://127.0.0.1:'+str(port)
 for attempt in range(40):
  try:
   with urllib.request.urlopen(base+'/api/health',timeout=1):break
  except Exception:time.sleep(.1)
 script="""import assert from 'node:assert/strict';const base=process.argv[1];
async function login(identity){const r=await fetch(base+'/api/collections/users/auth-with-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identity,password:'PrivateTest123!'})});assert.equal(r.status,200);return (await r.json()).token}
const parent=await login('assignment-parent@example.test'),expert=await login('assignment-expert@example.test'),foreign=await login('assignment-foreign@example.test'),other=await login('assignment-other@example.test');
async function req(path,token,method='GET',body){const r=await fetch(base+path,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});return {status:r.status,data:await r.json()}}
const cases=await req('/api/collections/cases/records',expert);assert.equal(cases.status,200);const caseId=cases.data.items.find(x=>x.name==='Private assigned case').id;const path='/api/dsc/expert/cases/'+caseId;const catalog=await req(path+'/assignment-tools?language=en',expert);if(catalog.status!==200)console.log(catalog);assert.equal(catalog.status,200);assert.ok(catalog.data.tools.length>=2);assert.ok(catalog.data.tools.some(t=>t.name_en==='Forbidden template'));const tool=catalog.data.tools.find(t=>t.name_en==='Practice writing');
assert.equal((await req(path+'/assignment-tools',foreign)).status,403);
assert.equal((await req(path+'/assignments',foreign,'POST',{tool_id:tool.id})).status,403);
assert.equal((await req(path+'/assignments',parent,'POST',{tool_id:tool.id})).status,403);
assert.equal((await req(path+'/assignments',expert,'POST',{})).status,400);
const missingId=cases.data.items.find(x=>x.name==='Uncorrected allocation case').id;const missing=await req('/api/dsc/expert/cases/'+missingId+'/assignment-tools',expert);assert.equal(missing.status,200);assert.equal(missing.data.tools.length,catalog.data.tools.length);
const created=await req(path+'/assignments',expert,'POST',{tool_id:tool.id,config:{forged:true},case:'forged',is_visible_to_user:false});if(created.status!==201)console.log(created);assert.equal(created.status,201);const id=created.data.id;
const list=await req('/api/dsc/my-assignments',parent);assert.equal(list.status,200);assert.ok(list.data.assignments.some(x=>x.id===id));const recordPath='/api/collections/case_tools/records/'+id;const detail=await req(recordPath,parent);assert.equal(detail.status,200);assert.equal(detail.data.config.questions[0].text,'Write a short paragraph about your day.');assert.equal(detail.data.config.forged,undefined);assert.equal(detail.data.is_not_template,false);assert.equal(detail.data.case,caseId);assert.equal(detail.data.is_visible_to_user,true);assert.equal(detail.data.name_en,'Practice writing');assert.equal(detail.data.name_ar,'');
assert.equal((await req(recordPath,other)).status,404);assert.equal((await req(recordPath,other,'PATCH',{status:'completed',responses:{answer:'Foreign answer'}})).status,404);
const answer=await req(recordPath,parent,'PATCH',{status:'completed',responses:{answer:'I finished the tool.'}});assert.equal(answer.status,200);assert.equal((await req(recordPath,parent,'PATCH',{config:{}})).status,404);assert.equal((await req(recordPath,parent,'PATCH',{is_visible_to_user:false})).status,404);assert.equal((await req(recordPath,expert)).data.responses.answer,'I finished the tool.');
console.log('Verified: catalog includes all active tools regardless of role; expert assigns the actual template configuration; parent opens and completes it; expert reads answers. Foreign access, tampered payloads are rejected; allocations without role_id can assign tools.');"""
 r=subprocess.run(['node','--input-type=module','-e',script,base],capture_output=True,text=True);print(r.stdout+r.stderr);assert r.returncode==0
finally:server.terminate();server.wait(timeout=8);log.close()
